-- Creation part 
CREATE DATABASE IF NOT EXISTS login;
USE login;
CREATE TABLE IF NOT EXISTS STUDENT_LOGIN (ROLL VARCHAR(20) NOT NULL PRIMARY KEY, PASSWORD VARCHAR(255) NOT NULL, CREATION_TIME TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS STUDENT (ROLL VARCHAR(20) NOT NULL PRIMARY KEY, NAME VARCHAR(100) NOT NULL, EMAIL VARCHAR(150) NOT NULL UNIQUE, DEPT VARCHAR(100) NOT NULL, SEM TINYINT UNSIGNED NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_student_login FOREIGN KEY (ROLL) REFERENCES STUDENT_LOGIN(ROLL) ON DELETE CASCADE, INDEX idx_student_name (NAME));
CREATE TABLE IF NOT EXISTS TEACHER_LOGIN (TID VARCHAR(20) NOT NULL PRIMARY KEY, PASSWORD VARCHAR(255) NOT NULL, CREATION_TIME TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS TEACHER (TID VARCHAR(20) NOT NULL PRIMARY KEY, NAME VARCHAR(100) NOT NULL, EMAIL VARCHAR(150) NOT NULL UNIQUE, DEPT VARCHAR(100) NOT NULL, DESIGNATION VARCHAR(80) NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_teacher_login FOREIGN KEY (TID) REFERENCES TEACHER_LOGIN(TID) ON DELETE CASCADE, INDEX idx_teacher_name (NAME));
CREATE TABLE IF NOT EXISTS SESSIONS (SESSION_ID CHAR(64) NOT NULL PRIMARY KEY, ACCOUNT_TYPE ENUM('student','teacher') NOT NULL, ROLL VARCHAR(20) NULL, TID VARCHAR(20) NULL, EXPIRES_AT DATETIME NOT NULL, CREATED_AT TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_session_student FOREIGN KEY (ROLL) REFERENCES STUDENT_LOGIN(ROLL) ON DELETE CASCADE, CONSTRAINT fk_session_teacher FOREIGN KEY (TID) REFERENCES TEACHER_LOGIN(TID) ON DELETE CASCADE, INDEX idx_sessions_roll (ROLL), INDEX idx_sessions_tid (TID), INDEX idx_sessions_exp (EXPIRES_AT), CONSTRAINT chk_session_owner CHECK ((ACCOUNT_TYPE = 'student' AND ROLL IS NOT NULL AND TID IS NULL) OR (ACCOUNT_TYPE = 'teacher' AND TID IS NOT NULL AND ROLL IS NULL)));
CREATE TABLE IF NOT EXISTS COURSES (COURSE_ID VARCHAR(20) NOT NULL PRIMARY KEY, COURSE_NAME VARCHAR(150) NOT NULL, CREDITS DECIMAL(3,1) DEFAULT 0.0, TID VARCHAR(20) NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, CONSTRAINT fk_course_teacher FOREIGN KEY (TID) REFERENCES TEACHER(TID) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS STU_COURSES (`S.ROLL` VARCHAR(20) NOT NULL, C_ID VARCHAR(20) NOT NULL, enrolled_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, status ENUM('enrolled','dropped','completed') NOT NULL DEFAULT 'enrolled', PRIMARY KEY (`S.ROLL`, C_ID), CONSTRAINT fk_stucourses_student FOREIGN KEY (`S.ROLL`) REFERENCES STUDENT(ROLL) ON DELETE CASCADE, CONSTRAINT fk_stucourses_course FOREIGN KEY (C_ID) REFERENCES COURSES(COURSE_ID) ON DELETE CASCADE, INDEX idx_stucourses_course (C_ID));
CREATE TABLE IF NOT EXISTS ASSESSMENTS (ASSESSMENT_ID INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, COURSE_ID VARCHAR(20) NOT NULL, TITLE VARCHAR(150) NOT NULL, MAX_MARKS DECIMAL(6,2) NOT NULL, WEIGHT DECIMAL(5,2) NOT NULL DEFAULT 100.00, ASSESSMENT_DATE DATE NOT NULL, CONSTRAINT fk_assessments_course FOREIGN KEY (COURSE_ID) REFERENCES COURSES(COURSE_ID) ON DELETE CASCADE, INDEX idx_assessments_course (COURSE_ID));
CREATE TABLE IF NOT EXISTS ACADEMICS (ASSESSMENT_ID INT UNSIGNED NOT NULL, `S.ROLL` VARCHAR(20) NOT NULL, SEM_MARKS DECIMAL(6,2) NOT NULL, REMARKS VARCHAR(255) NULL, entered_by VARCHAR(20) NULL, entered_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (ASSESSMENT_ID, `S.ROLL`), CONSTRAINT fk_academics_assessment FOREIGN KEY (ASSESSMENT_ID) REFERENCES ASSESSMENTS(ASSESSMENT_ID) ON DELETE CASCADE, CONSTRAINT fk_academics_teacher FOREIGN KEY (entered_by) REFERENCES TEACHER(TID) ON DELETE SET NULL, CONSTRAINT chk_marks CHECK (SEM_MARKS >= 0));
CREATE TABLE IF NOT EXISTS ATTENDENCE (ATTENDENCE_ID INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, COURSE_ID VARCHAR(20) NOT NULL, `S.ROLL` VARCHAR(20) NOT NULL, CLASS_DATE DATE NOT NULL, ATTENDENCE_STATUS ENUM('present','absent','late','excused') NOT NULL, marked_by VARCHAR(20) NULL, marked_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_attendence_course FOREIGN KEY (COURSE_ID) REFERENCES COURSES(COURSE_ID) ON DELETE CASCADE, CONSTRAINT fk_attendence_teacher FOREIGN KEY (marked_by) REFERENCES TEACHER(TID) ON DELETE SET NULL, UNIQUE KEY uq_attendence (COURSE_ID, `S.ROLL`, CLASS_DATE), INDEX idx_att_roll_date (`S.ROLL`, CLASS_DATE), INDEX idx_att_course_date (COURSE_ID, CLASS_DATE));
CREATE TABLE IF NOT EXISTS STUDY_MATERIALS (MATERIAL_ID INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, COURSE_ID VARCHAR(20) NULL, TITLE VARCHAR(200) NOT NULL, DESCRIPTION TEXT NULL, FILE_PATH VARCHAR(500) NOT NULL, FILE_TYPE VARCHAR(50) NOT NULL, FILE_SIZE BIGINT UNSIGNED DEFAULT 0, uploaded_by VARCHAR(20) NULL, UPLOAD_DATE TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_materials_course FOREIGN KEY (COURSE_ID) REFERENCES COURSES(COURSE_ID) ON DELETE CASCADE, CONSTRAINT fk_materials_teacher FOREIGN KEY (uploaded_by) REFERENCES TEACHER(TID) ON DELETE SET NULL, INDEX idx_materials_course (COURSE_ID));
CREATE TABLE IF NOT EXISTS NOTICES (NOTICE_ID INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, TITLE VARCHAR(200) NOT NULL, CONTENT TEXT NOT NULL, PRIORITY ENUM('low','normal','high','urgent') NOT NULL DEFAULT 'normal', AUDIENCE ENUM('all','students','teachers') NOT NULL DEFAULT 'all', posted_by VARCHAR(20) NULL, IS_PINNED TINYINT(1) NOT NULL DEFAULT 0, EXPIRES_AT DATETIME NULL, CREATED_AT TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_notices_teacher FOREIGN KEY (posted_by) REFERENCES TEACHER(TID) ON DELETE SET NULL, INDEX idx_notices_feed (IS_PINNED, CREATED_AT));

-- DROP VIEW IF EXISTS keeps the file re-runnable.
DROP VIEW IF EXISTS v_student_dashboard;
CREATE VIEW v_student_dashboard AS SELECT s.ROLL, s.NAME, s.DEPT, s.SEM, (SELECT COUNT(*) FROM STU_COURSES sc WHERE sc.`S.ROLL` = s.ROLL AND sc.status = 'enrolled') AS enrolled_courses, (SELECT COUNT(*) FROM ATTENDENCE a WHERE a.`S.ROLL` = s.ROLL AND a.CLASS_DATE >= CURDATE() - INTERVAL 30 DAY AND a.ATTENDENCE_STATUS IN ('present','late')) AS present_last_30, (SELECT COUNT(*) FROM ATTENDENCE a WHERE a.`S.ROLL` = s.ROLL AND a.CLASS_DATE >= CURDATE() - INTERVAL 30 DAY) AS total_last_30, (SELECT COUNT(*) FROM NOTICES n WHERE n.CREATED_AT >= CURDATE() - INTERVAL 7 DAY AND n.AUDIENCE IN ('all','students')) AS recent_notices, (SELECT COUNT(*) FROM STUDY_MATERIALS m JOIN STU_COURSES sc ON sc.C_ID = m.COURSE_ID WHERE sc.`S.ROLL` = s.ROLL AND m.UPLOAD_DATE >= CURDATE() - INTERVAL 7 DAY) AS new_materials FROM STUDENT s WHERE s.is_active = 1;

DROP VIEW IF EXISTS v_teacher_dashboard;
CREATE VIEW v_teacher_dashboard AS SELECT t.TID, t.NAME, t.DEPT, (SELECT COUNT(*) FROM COURSES c WHERE c.TID = t.TID) AS sections_teaching, (SELECT COUNT(*) FROM STU_COURSES sc JOIN COURSES c ON c.COURSE_ID = sc.C_ID WHERE c.TID = t.TID AND sc.status = 'enrolled') AS total_students, (SELECT COUNT(*) FROM STUDY_MATERIALS m WHERE m.uploaded_by = t.TID) AS materials_uploaded, (SELECT COUNT(*) FROM NOTICES n WHERE n.posted_by = t.TID) AS notices_posted FROM TEACHER t WHERE t.is_active = 1;
